@deco.set_separate_app_context(MONACO_APP_NAME)
def await_user_validation_dialog(waitTimeout:int = 20000) -> bool:
    """
    Wait for user validation dialog

    :param: waitTimeout (int): the wait timeout to be set.
    :return: a bool, True or False to indicate if the dialog exists or not
    """
    return True if CommonActions.wait_for_object_exists(MonacoCoreObjects.user_Validation_Dialog, waitTimeout) is not None else False

