@deco.set_separate_app_context(MONACO_APP_NAME)
def confirm_sucessful_login(waitTimeout: int=20000) -> bool:
    """Waits for the main Patient Selection dialog to appear and Returns True if it successfully does.

    :param waitTimeout int: Time in milliseconds to wait for the Monaco Patient Selection Dialog to appear.
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(MonacoCoreObjects.patient_Selection_Dialog, waitTimeout) is not None else False

@deco.set_separate_app_context(MONACO_APP_NAME)
def confirm_sucessful_login_with_adaptive_script(waitTimeout: int=10000) -> bool:
    """Waits for the main Monaco Workspace tree panel (on LHS) to appear and Returns True if it successfully does.

    :param waitTimeout int: Time in milliseconds to wait for the Monaco Workspace tree panel to appear.
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(MonacoCoreObjects.workspace_Panel_Study_Tree, waitTimeout) is not None else False

