@deco.set_separate_app_context(MONACO_APP_NAME)
def select_clinic(clinicName: str) -> None:
    """Locates the Clinc Selection dialog and searches the Clinc Tree for the given clinicName and selects it.

    :param clinicName: String value of the clinc to be searched for within the Clinic Tree.
    :type clinicName: str
    """
    target_clinic_object = CommonActions.get_child_object_by_exact_object_text(
        CommonActions.get_child_objects(MonacoCoreObjects.patient_Selection_Clinc_Tree_Installation_TreeItem),
        searchText=clinicName)
  
