@deco.set_separate_app_context(MONACO_APP_NAME)
def select_patient_by_text_and_column(patText:str, col:int) -> bool:
    """Locates the Patient Selection dialog > searches the Patient list table for the given text of the patient and the column index,
       and select/highlight the patient

    :params: patText (str): String value of the ID or name of the patient that will be selected from the Patient list table
             col (int): the column index, the ordinal number of the column from 1.

    :return: True if found and selected, False otherwise
    """
    children = CommonActions.get_children(MonacoCoreObjects.patient_Selection_Table) # type: ignore
    for child in children:
        if hasattr(child, 'id') and 'RowItem-' in child['id']:
            grandchildren = CommonActions.get_children(child) # type: ignore
            for gc in grandchildren:
                if hasattr(gc, 'id') and hasattr(gc, 'text') and (str(col) + ' - ' in gc['id'] and gc['text'] == patText):
                    CommonActions.mouse_move_and_press(gc)
                    time.sleep(1)
                    return True
    return False

