@deco.set_separate_app_context(MONACO_APP_NAME)
def right_click_patient_id_from_clinic_list(patientName: str) -> None:
    """Locates the Patient Selection dialog > searches the Patient ListView for the given patientName string and right clicks on the patient
    > Waits for the context menu item to appear

    :param patientName: String value of the Patient Name that will be selected from the Patient ListView
    :type patientName: str
    """
    patient_object_list = CommonActions.get_child_objects_by_object_type(
        CommonActions.get_child_objects(MonacoCoreObjects.patient_Selection_Patient_ListView),
        searchText="DataItem")

    for obj in patient_object_list:
        list_item_patient_name_cell = CommonActions.get_child_object_by_object_text(
            CommonActions.get_child_objects(obj),
            patientName)

        if list_item_patient_name_cell is not None:
            date_obj = CommonActions.get_child_object_by_object_id(
                CommonActions.get_child_objects(obj),
                "7 - 0"
            )
            CommonActions.right_click_object(date_obj)
            CommonActions.wait_for_object_to_appear(MonacoCoreObjects.patient_Selection_Main_Context_Menu)
            break

@deco.set_separate_app_context(MONACO_APP_NAME)
def check_for_mosaiq_patient_demographics_dialog(okWithEnterKey: bool = False) -> bool:
    """Checks for the MOSAIQ patient demographics cannot be found message dialod and acknowledge with
    the OK button.
    """
    try:
        if CommonActions.find_object(MonacoCoreObjects.monaco_Dialog) is not None:
            if okWithEnterKey:
                CommonActions.press_enter_key()
                return True
            else:
                CommonActions.left_click_object(MonacoCoreObjects.monaco_Dialog_OK_Button)
                return True
        return False
    except FailedToFindObject:
        return False

