@deco.set_separate_app_context(MONACO_APP_NAME)
def close_current_patient() -> None:
    """Locates the close patient icon button from the top menu using image verification and click on it
    """
    try:
        close_btn_image_path = os.path.abspath(os.path.join(CommonMonacoOps.get_monaco_image_folder_path(),
                                                            "monaco_close_patient_icon.png"))

        search_options = {"timeout": 15000, "threshold": 99.0}
        search_area = CommonActions.find_object(MonacoCoreObjects.monaco_Main_Window)

        close_patient_btn = CommonActions.wait_for_image_object(close_btn_image_path, search_options, search_area)
        if close_patient_btn is not None:
            CommonActions.left_click_object_no_move(close_patient_btn)
    except Exception as e:
        print(f"Close patient button image not found. An existing patient might not currently be open in Monaco. Warning: {e}")

@deco.set_separate_app_context(MONACO_APP_NAME)
def open_patient() -> None:
    """Locates the open patient icon button from the top menu using image verification and click on it
    """
    open_btn_image_path = os.path.abspath(os.path.join(CommonMonacoOps.get_monaco_image_folder_path(),
                                                            "monaco_open_patient_icon.png"))

    search_options = {"timeout": 5000, "threshold": 99.0}
    search_area = CommonActions.find_object(MonacoCoreObjects.monaco_Main_Window)

    open_patient_btn = CommonActions.wait_for_image_object(open_btn_image_path, search_options, search_area)
    if open_patient_btn is not None:
        CommonActions.left_click_object_no_move(open_patient_btn)

