@deco.set_separate_app_context(MONACO_APP_NAME)
def open_planning_toolbar(adaptive: bool = False) -> None:
    """Locates the top Monaco toolbar and selects the Planning tab item.

    :param bool adaptive: Value to determine if the Adaptive Planning object ID should be used for the tab item.
                          If Monaco has been launched via the adaptive planning workflow script, the object ID
                          for the planning tab item is different. If Monaco is launched normally, this can be
                          set to False to use the default object ID ("Planning")
    """
    if not adaptive:
        # Use the default object ID ("Planning") for the planning tab item.
        CommonActions.left_click_object(MonacoCoreObjects.toolBar_Planning_TabItem)
        #CommonActions.left_click_object(MonacoCoreObjects.toolBar_Fusion_TabItem)
    else:
        # If Monaco is started by the AdaptivePlanningWorkflow process/script the object ID for the planning tab item
        # is different (i.e. "AdaptivePlanning"), so use the alternate object definition.
        CommonActions.left_click_object(MonacoCoreObjects.toolBar_Adaptive_Planning_TabItem)

