    #         for plan_group in plan_groups:
    #             try:
    #                 CommonActions.expand_control(plan_group)
    #             except Exception:
    #                 pass
    #
    #             plan_list = CommonActions.get_child_objects_by_object_type(
    #                 CommonActions.get_child_objects(plan_group),
    #                 searchText="TreeItem")
    #             #print(f"Plan list found under group '{plan_group.text}': {[p.text for p in plan_list]}") #type: ignore
    #
    #             for plan in plan_list:
    #                 plan_text = plan.text.strip() #type: ignore
    #                 print(f"Plan: {plan_text}")
    #                 if plan_text == planName:
    #                     #print(f"Found plan: {plan.text} in Monaco Study Tree") #type: ignore
    #                     if loadIt:
    #                         #print(f"Double clicking plan: {plan.text} to open it in Monaco") #type: ignore
