def acknowledge_export_of_patient_shift_enabled_dialog(okWithEnterKey: bool = False) -> None:
    """Locates the Monaco dialog and checks for the "Automated export of the patient setup shift is enabled.
    Please confirm correct shift coordinates" message > Selects the OK button if dialog with matching text is found.

    Note: An issue has been observed where the Plan Approval window closes and the Monaco app minimizes itself when a
    mouse click is used to select the OK button. This issue does not occur when the Enter key is used to select the OK button.

    :param okWithEnterKey: Bool value to determine if the OK button should be selected with the Enter key instead of a mouse click.
    """
    try:
        if CommonActions.find_object(MonacoCoreObjects.monaco_Dialog) is not None:
            if "patient setup shift is enabled" in CommonActions.get_objects_text_value(CommonActions.find_object(MonacoCoreObjects.monaco_Dialog_Label)):
                if okWithEnterKey:
                    CommonActions.press_enter_key()
                else:
                    CommonActions.left_click_object(MonacoCoreObjects.monaco_Dialog_OK_Button)
    except FailedToFindObject:
        print("No Patient setup shift is enabled warning message to acknowledge")


@deco.set_separate_app_context(MONACO_APP_NAME)
def open_dicom_export_dialog() -> None:
    """Locates the Main DICOM Export button on the Output tool bar and clicks it > If the Patient Setup Shift Enabled dialog appears the OK button is selected >
    Then waits for the DICOM Export dialog to appear. NOTE: This may open the auto DICOM Export (DICOM Destinations) dialog depending on the auto DICOM Export
    settings in Monaco.
    """
    CommonActions.left_click_object(MonacoCoreObjects.output_Toolbar_Dicom_Export_Button)
    acknowledge_export_of_patient_shift_enabled_dialog()
    CommonActions.wait_for_object_to_appear(MonacoDicomExportObjects.dICOM_Export_Dialog)


@deco.set_separate_app_context(MONACO_APP_NAME)
def open_manual_or_auto_dicom_export_dialog(manualDicomExport: bool = True) -> None:
    """Locates the bottom half of the Main DICOM Export button on the Output tool bar and clicks it > Clicks either the Manual or Auto
    DICOM Export context menu item > If the Patient Setup Shift Enabled dialog appears the OK button is selected >
    Then waits for either the Manual DICOM Export dialog or the DICOM Destinations dialog to appear.

    Use this function to guarantee that either the Manual or Auto DICOM Export dialog is opened regardless of the default DICOM export settings.

    :param manualDicomExport: Bool value to determine if the Manual DICOM Export dialog should be opened. Set to False to open Auto DICOM Export dialog instead.
    """
    # Click on the bottom half of the DICOM Export button to open the Auto and Manual DICOM Export context menu item. Offset the bounding
    # rectangle height value within the main DICOM Export button object by 15 pixels
    CommonActions.mouse_click_specific_point_within_object(MonacoCoreObjects.output_Toolbar_Dicom_Export_Button, heightOffsetValue = 15)


    if manualDicomExport:
        export_menu_item = MonacoCoreObjects.manual_Dicom_Export_menu_item
        expected_export_dialog = MonacoDicomExportObjects.dICOM_Export_Dialog
    else:   # Auto DICOM export
        export_menu_item = MonacoCoreObjects.auto_Dicom_Export_menu_item
        expected_export_dialog = MonacoDicomExportObjects.dicom_Destinations_Dialog

    if CommonActions.find_any_object([export_menu_item], 500) is not None:
        CommonActions.left_click_object(export_menu_item)
    else:# work around if export_menu_item is not operable.
        CommonActions.press_tab_key()
        if manualDicomExport:
            CommonActions.press_tab_key()
        CommonActions.press_enter_key()

    acknowledge_export_of_patient_shift_enabled_dialog()
    CommonActions.wait_for_object_to_appear(expected_export_dialog)

