@deco.set_separate_app_context(MONACO_APP_NAME)
def confirm_notification(positive:bool):
    """
    Confirm the notification

    :param: positive (bool), True: confirm to click Yes button, No: if cancel.
    """
    obj = CommonActions.find_any_object([MonacoCoreObjects.monaco_Notification_Window, MonacoCoreObjects.monaco_Notification_Dialog], 2000)
    if obj:
        button = CommonActions.find_any_object([MonacoCoreObjects.notification_Yes_Button], 500) if positive else \
                CommonActions.find_any_object([MonacoCoreObjects.notification_No_Button], 500)
        if button is not None:
            CommonActions.click_button(button)
